const orderNumber = $input.first().json.orderNumber;

const orders = {
  "ORD-10245": {
    orderNumber: "ORD-10245",
    customerName: "Rahul",
    status: "Shipped",
    carrier: "Delhivery",
    trackingNumber: "DLV987654321",
    estimatedDelivery: "2026-10-09"
  },
  "ORD-10246": {
    orderNumber: "ORD-10246",
    customerName: "Amit",
    status: "Out for Delivery",
    carrier: "Blue Dart",
    trackingNumber: "BD123456789",
    estimatedDelivery: "2026-10-07"
  },
  "ORD-10247": {
    orderNumber: "ORD-10247",
    customerName: "Priya",
    status: "Processing",
    carrier: null,
    trackingNumber: null,
    estimatedDelivery: "2026-10-11"
  }
};

const order = orders[orderNumber];

if (!order) {
  return [
    {
      json: {
        found: false,
        orderNumber,
        message: `Order ${orderNumber} was not found.`
      }
    }
  ];
}

return [
  {
    json: {
      found: true,
      ...order
    }
  }
];
